mapper.select:
select sum(a.conMoneyTotal) as conMoneyTotalSum, sum(a.payApprovalTotal) as payApprovalTotalSum, sum(a.payYearTotal) as payYearTotalSum, sum(a.unPayAmtTotal) as unPayAmtTotalSum, sum(a.payDoneTotal) as payDoneTotalSum, sum(a.saApprovedAmtTotal) as saApprovedAmtTotalSum, sum(a.saContractorAmountTotal) as saContractorAmountTotalSum, sum(a.saSupervisorAmountTotal) as saSupervisorAmountTotalSum, sum(a.saCostConsultTotal) as saCostConsultAmountTotalSum, sum(a.ecApplyMoneyTotal) as ecApplyMoneyTotalSum, sum(a.ecfApplyMoneyTotal) as ecfApplyMoneyTotalSum, sum(a.isPaymentAmtTotal) as isPaymentAmtTotalSum, sum(a.ciCollectTaxAmtTotal) as ciCollectTaxAmtTotalSum, sum(a.isActualAmtTotal) as isActualAmtTotalSum from( select mn.Con_Money_Total as conMoneyTotal, (select sum(pay.Pay_Apply) from Con_Pay pay where pay.Con_Id=mn.Con_Id and pay.Pay_State=7 and pay.Pay_Category='01') as payApprovalTotal, (select sum(pay.Pay_Apply) from Con_Pay pay where pay.Con_Id=mn.Con_Id and pay.Pay_State=7 and pay.Pay_Category='01'
) as payYearTotal, mn.Con_Money_Total-(select sum(pay.Pay_Apply) from Con_Pay pay where pay.Con_Id=mn.Con_Id and pay.Pay_State=7 and pay.Pay_Category='01') as unPayAmtTotal, (select sum(pay.Pay_Done) from Con_Pay pay where pay.Con_Id=mn.Con_Id and pay.Pay_State=7 and pay.Pay_Category='01') as payDoneTotal, (select sum(sam.Sa_Approved_Amt) from Inv_Settlement_Apply sam where sam.Con_Id=mn.Con_Id and sam.Sa_State=7) as saApprovedAmtTotal, (select sum(sam.Sa_Contractor_Amount) from Inv_Settlement_Apply sam where sam.Con_Id=mn.Con_Id and sam.Sa_State=7) as saContractorAmountTotal, (select sum(sam.Sa_Supervisor_Amount) from Inv_Settlement_Apply sam where sam.Con_Id=mn.Con_Id and sam.Sa_State=7) as saSupervisorAmountTotal, (select sum(sam.Sa_Cost_Consult_Amount) from Inv_Settlement_Apply sam where sam.Con_Id=mn.Con_Id and sam.Sa_State=7) as saCostConsultTotal, (select sum(sam.Ec_Apply_Money) from Con_EC sam where sam.Con_Id=mn.Con_Id and sam.Ec_State=7) as ecApplyMoneyTotal, (select sum(case when sam.Ecf_Apply_Money_Type=1 then sam.Ecf_Apply_Money else -1*sam.Ecf_Apply_Money end) from Con_EC_Fee sam where sam.Con_Id=mn.Con_Id and sam.Ecf_State=7) as ecfApplyMoneyTotal, (select sum(cis.Is_Payment_Amt) from Con_Invoice_Sign cis where cis.Con_Id=mn.Con_Id and cis.state=7) as isPaymentAmtTotal, (select sum(ci.Ci_Collect_Tax_Amt) from Con_Invoice_Info ci left join Con_Invoice_Sign cis on cis.id=ci.Is_id where cis.Con_Id=mn.Con_Id and cis.state=7) as ciCollectTaxAmtTotal, (select sum(cis.Is_Actual_Amt) from Con_Invoice_Sign cis where cis.Con_Id=mn.Con_Id and cis.state=7) as isActualAmtTotal, ly.Sa_Approved_Amt as saApprovedAmt from Con_Contract mn left join Pre_Project pro on mn.con_Project_Id=pro.P_Id left join SYS_Company c on mn.con_Party_B_Id=c.C_Id left join SYS_Company c1 on mn.Con_Party_A_Id=c1.C_Id left join Con_Invoice_Sign csi on csi.Con_Id=mn.Con_Id left join Inv_Settlement_Apply ly on ly.con_id = mn.con_id
) a

select f.T_Code as tCode, pro.P_Name as pName, pro.P_Name as pCode, c.C_Name as conPartyBName, c1.C_Name as conPartyAName, mn.Con_Id as conId, mn.Con_Name as conName, mn.Con_Code as conCode, mn.Con_Party_A_Id as conPartyAId, mn.Con_Party_B_Id as conPartyBId, mn.Con_Type as conType, mn.Con_Money_Total as conMoneyTotal, mn.Con_State as conState, mn.Con_Rate as conRate, mn.Con_Money_Rate as conMoneyRate, mn.Con_Execution as conExecution, mn.Con_Plan_Start_Date as conPlanStartDate, mn.Con_Plan_End_Date as conPlanEndDate, (select SUM(cpfa.cpaf_Application) from Con_Pay_Apply_Flow cpfa where cpfa.con_id=mn.con_id and cpfa.state=7) as cpafApplicationSum, (select sum(pay.Pay_Apply) from Con_Pay pay where pay.Con_Id=mn.Con_Id and pay.Pay_State=7 and pay.Pay_Category='01') as payApprovalTotal, (select sum(pay.pay_Approval) from Con_Pay pay where pay.Con_Id=mn.Con_Id and pay.Pay_State=7 and pay.Pay_Category='01') as payApprovalSum, (select sum(pay.Pay_Apply) from Con_Pay pay where pay.Con_Id=mn.Con_Id and pay.Pay_State=7 and pay.Pay_Category='01'
) as payYearTotal, mn.Con_Money_Total-(select sum(pay.Pay_Apply) from Con_Pay pay where pay.Con_Id=mn.Con_Id and pay.Pay_State=7 and pay.Pay_Category='01') as unPayAmtTotal, (select sum(pay.Pay_Done) from Con_Pay pay where pay.Con_Id=mn.Con_Id and pay.Pay_State=7 and pay.Pay_Category='01') as payDoneTotal, (select sum(sam.Sa_Approved_Amt) from Inv_Settlement_Apply sam where sam.Con_Id=mn.Con_Id and sam.Sa_State=7) as saApprovedAmtTotal, (select sum(sam.Sa_Contractor_Amount) from Inv_Settlement_Apply sam where sam.Con_Id=mn.Con_Id and sam.Sa_State=7) as saContractorAmountTotal, (select sum(sam.Sa_Supervisor_Amount) from Inv_Settlement_Apply sam where sam.Con_Id=mn.Con_Id and sam.Sa_State=7) as saSupervisorAmountTotal, (select sum(sam.Sa_Cost_Consult_Amount) from Inv_Settlement_Apply sam where sam.Con_Id=mn.Con_Id and sam.Sa_State=7) as saCostConsultTotal, (select sum(sam.Ec_Apply_Money) from Con_EC sam where sam.Con_Id=mn.Con_Id and sam.Ec_State=7) as ecApplyMoneyTotal, (select sum(case when sam.Ecf_Apply_Money_Type=1 then sam.Ecf_Apply_Money else -1*sam.Ecf_Apply_Money end) from Con_EC_Fee sam where sam.Con_Id=mn.Con_Id and sam.Ecf_State=7) as ecfApplyMoneyTotal, (select sum(cis.Is_Payment_Amt) from Con_Invoice_Sign cis where cis.Con_Id=mn.Con_Id and cis.state=7) as isPaymentAmtTotal, (select sum(ci.Ci_Collect_Tax_Amt) from Con_Invoice_Info ci left join Con_Invoice_Sign cis on cis.id=ci.Is_id where cis.Con_Id=mn.Con_Id and cis.state=7) as ciCollectTaxAmtTotal, (select sum(cis.Is_Actual_Amt) from Con_Invoice_Sign cis where cis.Con_Id=mn.Con_Id and cis.state=7) as isActualAmtTotal, ly.Sa_Approved_Amt as saApprovedAmt from Con_Contract mn left join Pre_Project pro on mn.con_Project_Id=pro.P_Id left join SYS_Company c on mn.con_Party_B_Id=c.C_Id left join SYS_Company c1 on mn.Con_Party_A_Id=c1.C_Id left join Con_Invoice_Sign csi on csi.Con_Id=mn.Con_Id left join Sys_File f on f.FileID=mn.Con_Id left join Inv_Settlement_Apply ly on ly.con_id = mn.con_id
order by mn.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
order by mn.Con_Create_Time desc

