select
pro.P_Name as conProjectName, c.C_Name as conPartyBName, c1.C_Name as conPartyAName, c2.C_Name as conPartyAOtherName, c.C_Abbreviation as conPartyBAbbName, c1.C_Abbreviation as conPartyAAbbName, c2.C_Abbreviation as conPartyAOtherAbbName, con.Con_Name as conRelieveConName, con.Con_Code as conRelieveConCode, sec.Sec_Name as secName, bdd.Bdd_Name as bddName, bdd.Bdd_Code as bddCode, bdd.Bdd_Unit as bddUnit, bdd.Bdd_Count as bddCount, bdd.Bdd_Price as bddPrice, bdd.Bdd_Total as bddTotal, mn.* from Con_Contract mn left join Pre_Project pro on mn.con_Project_Id=pro.P_Id
left join SYS_Company c on mn.con_Party_B_Id=c.C_Id left join SYS_Company c1 on mn.Con_Party_A_Id=c1.C_Id left join SYS_Company c2 on mn.Con_Party_A_Other_Id=c2.C_Id left join Con_Contract con on mn.Con_Relieve_Con_Id=con.Con_Id left join Sec_Info sec on sec.Sec_Id=mn.Con_Section_Id left join Inv_Budget_Declare_Dtl bdd on bdd.Bdd_Id=mn.Con_Budget_Id ${params.authSql}
