select
pro.P_Name as conProjectName, pro.P_Building_Scale as pBuildingScale, c.C_Name as conPartyBName, c1.C_Name as conPartyAName, c2.C_Name as conPartyAOtherName, c3.C_Name as conPartyCName, c4.C_Name as conEvaluateBName, c5.C_Name as conEvaluateAName, c.C_Abbreviation as conPartyBAbbName, c1.C_Abbreviation as conPartyAAbbName, c2.C_Abbreviation as conPartyAOtherAbbName, con.Con_Name as conRelieveConName, con.Con_Code as conRelieveConCode, con1.Con_Name as conEvaluateName, con1.Con_Code as conEvaluateCode, con1.Con_Provisional_Pe as conEvaluatePeAmt, sec.Sec_Name as secName, sdep.D_Name as conDepName, (select sum(isa.Sa_Approved_Amt) from Inv_Settlement_Apply isa where isa.Con_Id=mn.Con_Id and isa.Sa_State=7) as saApprovedAmtSum, (select count(*) from con_contract cone where cone.Con_Evaluate_Id=mn.con_Id and cone.Con_Approval_State=7) as conEvaluateCount, (select sum(cone.Con_Money_Total) from con_contract cone where cone.Con_Evaluate_Id=mn.con_Id and cone.Con_Approval_State=7) as conEvaluateAmt, (select count(cone.Con_Money_Total) from con_contract cone where cone.Con_Master_Con_Id=mn.con_Id and cone.Con_Approval_State=7) as conMasterAmt, (select count(*) from con_contract cone where cone.Con_Master_Con_Id=mn.con_Id and cone.Con_Approval_State=7) as conMasterCount, mn.*, jl.Con_Name as conJlName, sf.file_relation_id as fileRelationId from Con_Contract mn left join Pre_Project pro on mn.con_Project_Id=pro.P_Id
left join SYS_Department sdep on sdep.D_Id=mn.Con_Department left join SYS_Company c on mn.con_Party_B_Id=c.C_Id left join SYS_Company c1 on mn.Con_Party_A_Id=c1.C_Id left join SYS_Company c2 on mn.Con_Party_A_Other_Id=c2.C_Id left join SYS_Company c3 on mn.Con_Party_C_Id=c3.C_Id left join Con_Contract con on mn.Con_Relieve_Con_Id=con.Con_Id left join Con_Contract con1 on mn.Con_Evaluate_Id=con1.Con_Id left join SYS_Company c4 on con1.con_Party_B_Id=c4.C_Id left join SYS_Company c5 on con1.Con_Party_A_Id=c5.C_Id left join Sec_Info sec on sec.Sec_Id=mn.Con_Section_Id left join Con_Contract jl on mn.Con_JL_Id = jl.Con_Id left join SYS_File sf on sf.FileID = mn.Con_Id ${params.authSql}
order by mn.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
order by mn.Con_Create_Time desc

select
pro.P_Name as conProjectName, c.C_Name as conPartyBName, c1.C_Name as conPartyAName, c2.C_Name as conPartyAOtherName, c3.C_Name as conPartyCName, c4.C_Name as conEvaluateBName, c5.C_Name as conEvaluateAName, c.C_Abbreviation as conPartyBAbbName, c1.C_Abbreviation as conPartyAAbbName, c2.C_Abbreviation as conPartyAOtherAbbName, con.Con_Name as conRelieveConName, con.Con_Code as conRelieveConCode, con1.Con_Name as conEvaluateName, con1.Con_Code as conEvaluateCode, con1.Con_Provisional_Pe as conEvaluatePeAmt, sec.Sec_Name as secName, sdep.D_Name as conDepName, (select sum(isa.Sa_Approved_Amt) from Inv_Settlement_Apply isa where isa.Con_Id=mn.Con_Id and isa.Sa_State=7) as saApprovedAmtSum, (select count(*) from con_contract cone where cone.Con_Evaluate_Id=mn.con_Id and cone.Con_Approval_State=7) as conEvaluateCount, (select sum(cone.Con_Money_Total) from con_contract cone where cone.Con_Evaluate_Id=mn.con_Id and cone.Con_Approval_State=7) as conEvaluateAmt, (select count(cone.Con_Money_Total) from con_contract cone where cone.Con_Master_Con_Id=mn.con_Id and cone.Con_Approval_State=7) as conMasterAmt, (select count(*) from con_contract cone where cone.Con_Master_Con_Id=mn.con_Id and cone.Con_Approval_State=7) as conMasterCount, mn.*, jl.Con_Name as conJlName from Con_Contract mn left join Pre_Project pro on mn.con_Project_Id=pro.P_Id
left join SYS_Department sdep on sdep.D_Id=mn.Con_Department left join SYS_Company c on mn.con_Party_B_Id=c.C_Id left join SYS_Company c1 on mn.Con_Party_A_Id=c1.C_Id left join SYS_Company c2 on mn.Con_Party_A_Other_Id=c2.C_Id left join SYS_Company c3 on mn.Con_Party_C_Id=c3.C_Id left join Con_Contract con on mn.Con_Relieve_Con_Id=con.Con_Id left join Con_Contract con1 on mn.Con_Evaluate_Id=con1.Con_Id left join SYS_Company c4 on con1.con_Party_B_Id=c4.C_Id left join SYS_Company c5 on con1.Con_Party_A_Id=c5.C_Id left join Sec_Info sec on sec.Sec_Id=mn.Con_Section_Id left join Con_Contract jl on mn.Con_JL_Id = jl.Con_Id ${params.authSql}
and mn.Con_Approval_State!=3 and mn.Con_Approval_State!=0
order by mn.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
order by mn.Con_Create_Time desc

select
pro.P_Name as conProjectName, c.C_Name as conPartyBName, c1.C_Name as conPartyAName, c2.C_Name as conPartyAOtherName, c3.C_Name as conPartyCName, c4.C_Name as conEvaluateBName, c5.C_Name as conEvaluateAName, c.C_Abbreviation as conPartyBAbbName, c1.C_Abbreviation as conPartyAAbbName, c2.C_Abbreviation as conPartyAOtherAbbName, con.Con_Name as conRelieveConName, con.Con_Code as conRelieveConCode, con1.Con_Name as conEvaluateName, con1.Con_Code as conEvaluateCode, con1.Con_Provisional_Pe as conEvaluatePeAmt, sec.Sec_Name as secName, sdep.D_Name as conDepName, (select sum(isa.Sa_Approved_Amt) from Inv_Settlement_Apply isa where isa.Con_Id=mn.Con_Id and isa.Sa_State=7) as saApprovedAmtSum, (select count(*) from con_contract cone where cone.Con_Evaluate_Id=mn.con_Id and cone.Con_Approval_State=7) as conEvaluateCount, (select sum(cone.Con_Money_Total) from con_contract cone where cone.Con_Evaluate_Id=mn.con_Id and cone.Con_Approval_State=7) as conEvaluateAmt, (select count(cone.Con_Money_Total) from con_contract cone where cone.Con_Master_Con_Id=mn.con_Id and cone.Con_Approval_State=7) as conMasterAmt, (select count(*) from con_contract cone where cone.Con_Master_Con_Id=mn.con_Id and cone.Con_Approval_State=7) as conMasterCount, mn.* from Con_Contract mn left join Pre_Project pro on mn.con_Project_Id=pro.P_Id
left join SYS_Department sdep on sdep.D_Id=mn.Con_Department left join SYS_Company c on mn.con_Party_B_Id=c.C_Id left join SYS_Company c1 on mn.Con_Party_A_Id=c1.C_Id left join SYS_Company c2 on mn.Con_Party_A_Other_Id=c2.C_Id left join SYS_Company c3 on mn.Con_Party_C_Id=c3.C_Id left join Con_Contract con on mn.Con_Relieve_Con_Id=con.Con_Id left join Con_Contract con1 on mn.Con_Evaluate_Id=con1.Con_Id left join SYS_Company c4 on con1.con_Party_B_Id=c4.C_Id left join SYS_Company c5 on con1.Con_Party_A_Id=c5.C_Id left join Sec_Info sec on sec.Sec_Id=mn.Con_Section_Id ${params.authSql}
and mn.con_id not in (SELECT dp.contract_id FROM dangerous_project dp WHERE dp.project_id = #{params.conProjectId} and dp.approve_status = 7)
order by mn.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
order by mn.Con_Create_Time desc

mapper.select:
select pro.P_Name as pName, pro.P_Code as pCode, mn.con_Project_Id as conProjectId, mn.Con_Approval_State as conApprovalState, mn.Con_Id as conId, mn.Con_Name as conName, mn.Con_Code as conCode, mn.Con_Type as conType from Con_Contract mn left join Pre_Project pro on mn.con_Project_Id=pro.P_Id WHERE 1=1
order by mn.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
