select
pro.P_Name as conProjectName, c.C_Name as conPartyBName, c1.C_Name as conPartyAName, c3.C_Name as conPartyCName, c.C_Abbreviation as conPartyBAbbName, c1.C_Abbreviation as conPartyAAbbName, c2.C_Abbreviation as conPartyAOtherAbbName, con1.Con_Provisional_Pe as conEvaluatePeAmt, mn.* from Con_Contract mn left join Pre_Project pro on mn.con_Project_Id=pro.P_Id
left join SYS_Department sdep on sdep.D_Id=mn.Con_Department left join SYS_Company c on mn.con_Party_B_Id=c.C_Id left join SYS_Company c1 on mn.Con_Party_A_Id=c1.C_Id left join SYS_Company c2 on mn.Con_Party_A_Other_Id=c2.C_Id left join SYS_Company c3 on mn.Con_Party_C_Id=c3.C_Id left join Con_Contract con on mn.Con_Relieve_Con_Id=con.Con_Id left join Con_Contract con1 on mn.Con_Evaluate_Id=con1.Con_Id left join SYS_Company c4 on con1.con_Party_B_Id=c4.C_Id left join SYS_Company c5 on con1.Con_Party_A_Id=c5.C_Id left join Sec_Info sec on sec.Sec_Id=mn.Con_Section_Id left join Con_Contract jl on mn.Con_JL_Id = jl.Con_Id ${params.authSql}
order by mn.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
order by mn.Con_Create_Time desc

select ${selectClause} from Con_Contract mn left join Pre_Project pro on mn.con_Project_Id=pro.P_Id
left join SYS_Department sdep on sdep.D_Id=mn.Con_Department left join SYS_Company c on mn.con_Party_B_Id=c.C_Id left join SYS_Company c1 on mn.Con_Party_A_Id=c1.C_Id left join SYS_Company c2 on mn.Con_Party_A_Other_Id=c2.C_Id left join SYS_Company c3 on mn.Con_Party_C_Id=c3.C_Id left join Con_Contract con on mn.Con_Relieve_Con_Id=con.Con_Id left join Con_Contract con1 on mn.Con_Evaluate_Id=con1.Con_Id left join SYS_Company c4 on con1.con_Party_B_Id=c4.C_Id left join SYS_Company c5 on con1.Con_Party_A_Id=c5.C_Id left join Sec_Info sec on sec.Sec_Id=mn.Con_Section_Id left join Con_Contract jl on mn.Con_JL_Id=jl.Con_Id ${params.authSql}
and mn.Con_Approval_State!=3 and mn.Con_Approval_State!=0

select
pro.P_Name as conProjectName, pro.P_Building_Scale as pBuildingScale, c.C_Name as conPartyBName, c1.C_Name as conPartyAName, c2.C_Name as conPartyAOtherName, c3.C_Name as conPartyCName, c4.C_Name as conEvaluateBName, c5.C_Name as conEvaluateAName, c.C_Abbreviation as conPartyBAbbName, c1.C_Abbreviation as conPartyAAbbName, c2.C_Abbreviation as conPartyAOtherAbbName, con.Con_Name as conRelieveConName, con.Con_Code as conRelieveConCode, con1.Con_Name as conEvaluateName, con1.Con_Code as conEvaluateCode, con1.Con_Provisional_Pe as conEvaluatePeAmt, sec.Sec_Name as secName, sdep.D_Name as conDepName, sa.saApprovedAmtSum, eval.conEvaluateCount, eval.conEvaluateAmt, master.conMasterAmt, master.conMasterCount, mn.*, jl.Con_Name as conJlName, ca.Ca_Date as completeDate, ca.commencement_Time as commencementTime, ise.State_Time as endTime, ise.Sae_Audit_Report as auditReport, cp.Warranty_Refund_Time as warrantyRefundTime from Con_Contract mn left join Pre_Project pro on mn.con_Project_Id=pro.P_Id
left join SYS_Department sdep on sdep.D_Id=mn.Con_Department left join SYS_Company c on mn.con_Party_B_Id=c.C_Id left join SYS_Company c1 on mn.Con_Party_A_Id=c1.C_Id left join SYS_Company c2 on mn.Con_Party_A_Other_Id=c2.C_Id left join SYS_Company c3 on mn.Con_Party_C_Id=c3.C_Id left join Con_Contract con on mn.Con_Relieve_Con_Id=con.Con_Id left join Con_Contract con1 on mn.Con_Evaluate_Id=con1.Con_Id left join SYS_Company c4 on con1.con_Party_B_Id=c4.C_Id left join SYS_Company c5 on con1.Con_Party_A_Id=c5.C_Id left join Sec_Info sec on sec.Sec_Id=mn.Con_Section_Id left join Con_Contract jl on mn.Con_JL_Id = jl.Con_Id left join completion_acceptance ca on mn.con_Id=ca.con_Id and ca.Ca_State = 7 left join inv_settlement_end_gg ise on mn.con_Id=ise.con_Id and ise.State = 7 left join ( select Con_Id, sum(Sa_Approved_Amt) as saApprovedAmtSum from Inv_Settlement_Apply where Sa_State=7 group by Con_Id ) sa on sa.Con_Id = mn.Con_Id left join ( select Con_Evaluate_Id, count(*) as conEvaluateCount, sum(Con_Money_Total) as conEvaluateAmt from con_contract where Con_Approval_State=7 and Con_Evaluate_Id is not null group by Con_Evaluate_Id ) eval on eval.Con_Evaluate_Id = mn.con_Id left join ( select Con_Master_Con_Id, count(*) as conMasterCount, count(Con_Money_Total) as conMasterAmt from con_contract where Con_Approval_State=7 and Con_Master_Con_Id is not null group by Con_Master_Con_Id ) master on master.Con_Master_Con_Id = mn.con_Id left join (
) cp on mn.con_Id=cp.Con_Id ${params.authSql}
and exists (select 1 from Pro_Sources_Funds psf where psf.P_ID=mn.con_Project_Id and psf.Fs_Cost_Code like concat('%',#{params.fsCostCode},'%'))
and pro.P_Campus = #{params.pCampus}
and pro.P_Type = #{params.pType}
and pro.P_Building_Scale = #{params.pBuildingScale}
and mn.Con_Term = #{params.conTerm}
and mn.Con_Start_Date >= #{params.startDateStart}
and mn.Con_Start_Date <= #{params.startDateEnd}
and ca.Ca_Date >= #{params.completeDateStart}
and ca.Ca_Date <= #{params.completeDateEnd}
and ise.Sae_Audit_End_Time >= #{params.endTimeStart}
and ise.Sae_Audit_End_Time <= #{params.endTimeEnd}
order by mn.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
order by mn.Con_Create_Time desc

