select sum(Con_Money_Total)
from Con_Contract
where Con_Project_Id = #{pId}

select count(cbId)
from (
select distinct Con_Party_B_Id as cbId from Con_Contract where Con_Approval_State!=3 and Te_Id = #{teId}
union
select distinct Con_Party_B1 as cbId from Con_Contract where Con_Approval_State!=3 and Te_Id = #{teId}
union
select distinct Con_Party_B2 as cbId from Con_Contract where Con_Approval_State!=3 and Te_Id = #{teId}
union
select distinct Con_Party_B3 as cbId from Con_Contract where Con_Approval_State!=3 and Te_Id = #{teId}
union
select distinct Con_Party_B4 as cbId from Con_Contract where Con_Approval_State!=3 and Te_Id = #{teId}
union
select distinct Con_Party_B5 as cbId from Con_Contract where Con_Approval_State!=3 and Te_Id = #{teId}
union
select distinct Con_Party_C_Id as cbId from Con_Contract where Con_Approval_State!=3 and Te_Id = #{teId}
union
select distinct Con_Party_D_Id as cbId from Con_Contract where Con_Approval_State!=3 and Te_Id = #{teId}
) a

select count(cbId)
from (
select distinct Con_Party_B_Id as cbId from Con_Contract where Con_Approval_State!=3 and Te_Id = #{teId} 
union
select distinct Con_Party_B1 as cbId from Con_Contract where Con_Approval_State!=3 and Te_Id = #{teId} 
union
select distinct Con_Party_B2 as cbId from Con_Contract where Con_Approval_State!=3 and Te_Id = #{teId} 
union
select distinct Con_Party_B3 as cbId from Con_Contract where Con_Approval_State!=3 and Te_Id = #{teId} 
union
select distinct Con_Party_B4 as cbId from Con_Contract where Con_Approval_State!=3 and Te_Id = #{teId} 
union
select distinct Con_Party_B5 as cbId from Con_Contract where Con_Approval_State!=3 and Te_Id = #{teId} 
union
select distinct Con_Party_C_Id as cbId from Con_Contract where Con_Approval_State!=3 and Te_Id = #{teId} 
union
select distinct Con_Party_D_Id as cbId from Con_Contract where Con_Approval_State!=3 and Te_Id = #{teId} 
) a

select
pro.P_Name as conProjectName, pro.p_id as pId, c.C_Name as conPartyBName, c1.C_Name as conPartyAName, c2.C_Name as conPartyAOtherName, c3.C_Name as conPartyCName, c4.C_Name as conEvaluateBName, c5.C_Name as conEvaluateAName, c.C_Abbreviation as conPartyBAbbName, c1.C_Abbreviation as conPartyAAbbName, c2.C_Abbreviation as conPartyAOtherAbbName, con.Con_Name as conRelieveConName, con.Con_Code as conRelieveConCode, con1.Con_Name as conEvaluateName, con1.Con_Code as conEvaluateCode, con1.Con_Provisional_Pe as conEvaluatePeAmt, sec.Sec_Name as secName, sdep.D_Name as conDepName, mn.*, jl.Con_Name as conJlName, bp.bp_Payable as bpPayable, bp.bp_Actual_Application as bpActualApplication, bp.bp_Application_Date as bpApplicationDate, bp.create_Uname as bpCreateUname, bp.state as bpState, c6.c_name as conPayeeName, mn.con_Payee_Id as conPayeeId from Con_Contract mn left join Pre_Project pro on mn.con_Project_Id=pro.P_Id
left join SYS_Department sdep on sdep.D_Id=mn.Con_Department left join SYS_Company c on mn.con_Party_B_Id=c.C_Id left join SYS_Company c1 on mn.Con_Party_A_Id=c1.C_Id left join SYS_Company c2 on mn.Con_Party_A_Other_Id=c2.C_Id left join SYS_Company c3 on mn.Con_Party_C_Id=c3.C_Id left join Con_Contract con on mn.Con_Relieve_Con_Id=con.Con_Id left join Con_Contract con1 on mn.Con_Evaluate_Id=con1.Con_Id left join SYS_Company c4 on con1.con_Party_B_Id=c4.C_Id left join SYS_Company c5 on con1.Con_Party_A_Id=c5.C_Id left join Sec_Info sec on sec.Sec_Id=mn.Con_Section_Id left join Con_Contract jl on mn.Con_JL_Id = jl.Con_Id left join Balance_Payment bp on bp.Con_Id = mn.Con_Id left join SYS_Company c6 on mn.con_Payee_Id=c6.C_Id
INNER JOIN ( SELECT Con_Id FROM Con_Contract_Pay_Plan
and Cpp_Condition_Type = #{params.pddPayType}
GROUP BY Con_Id ) p ON mn.Con_Id = p.Con_Id ${params.authSql}
and mn.con_Party_A_Agent like concat('%',#{params.conPartyAAgent},'%')
and pro.p_id = #{params.pId}
and pro.p_name like concat('%',#{params.pName},'%')

select SUM(mn.Con_Money_Total) as totalMoney from con_contract mn left join pre_project pp on mn.con_Project_Id=pp.p_id left join sys_company sc on mn.con_Party_B_Id=sc.c_id left join completion_acceptance ca on mn.con_Id=ca.con_Id left join inv_settlement_end_gg ise on mn.con_Id=ise.con_Id left join Pro_Sources_Funds psf on pp.P_Id=psf.P_Id ${authSql}
and pp.P_Name like concat('%', #{params.pName}, '%')
and mn.Con_Name like concat('%', #{params.conName}, '%')
and mn.Con_Code like concat('%', #{params.conCode}, '%')
and mn.Con_Category=#{params.conCategory}

select
    mn.*,
    pp.P_Name as conProjectName,
    c.C_Name as conPartyBName
from con_contract mn
left join sys_company c on mn.con_Party_B_Id=c.c_id
left join pre_project pp on mn.con_Project_Id=pp.p_id
where 1=1

    and mn.con_Project_Id=#{params.pId}


    and mn.Con_Name like concat('%', #{params.conName}, '%')


    and mn.Con_Code like concat('%', #{params.conCode}, '%')


    and mn.Con_Category= #{params.conCategory}


    and mn.Con_State= #{params.conState}


    and mn.Con_Approval_State= #{params.conApprovalState}


    and c.C_Name like concat('%', #{params.conPartyBName}, '%')


    and mn.Con_Type= #{params.conType}

select

pro.P_Name as conProjectName,
pro.P_Building_Scale as pBuildingScale,
CONCAT_WS('；', c.C_Name, cc1.C_Name, cc2.C_Name, cc3.C_Name, cc4.C_Name, cc5.C_Name, c3.C_Name, cc6.C_Name)
as conPartyBName,
c1.C_Name as conPartyAName,
c2.C_Name as conPartyAOtherName,
c3.C_Name as conPartyCName,
c4.C_Name as conEvaluateBName,
c5.C_Name as conEvaluateAName,
c.C_Abbreviation as conPartyBAbbName,
c1.C_Abbreviation as conPartyAAbbName,
c2.C_Abbreviation as conPartyAOtherAbbName,
con.Con_Name as conRelieveConName,
con.Con_Code as conRelieveConCode,
con1.Con_Name as conEvaluateName,
con1.Con_Code as conEvaluateCode,
con1.Con_Provisional_Pe as conEvaluatePeAmt,
sec.Sec_Name as secName,
sdep.D_Name as conDepName,
mn.*,
jl.Con_Name  as conJlName
from Con_Contract mn
left join Pre_Project pro on mn.con_Project_Id=pro.P_Id

left join SYS_Department sdep on sdep.D_Id=mn.Con_Department
left join SYS_Company c on mn.con_Party_B_Id=c.C_Id
left join SYS_Company cc1 on mn.con_Party_B1=c.C_Id
left join SYS_Company cc2 on mn.con_Party_B2=c.C_Id
left join SYS_Company cc3 on mn.con_Party_B3=c.C_Id
left join SYS_Company cc4 on mn.con_Party_B4=c.C_Id
left join SYS_Company cc5 on mn.con_Party_B5=c.C_Id
left join SYS_Company cc6 on mn.Con_Party_D_Id=cc6.C_Id
left join SYS_Company c1 on mn.Con_Party_A_Id=c1.C_Id
left join SYS_Company c2 on mn.Con_Party_A_Other_Id=c2.C_Id
left join SYS_Company c3 on mn.Con_Party_C_Id=c3.C_Id
left join Con_Contract con on mn.Con_Relieve_Con_Id=con.Con_Id
left join Con_Contract con1 on mn.Con_Evaluate_Id=con1.Con_Id
left join SYS_Company c4 on con1.con_Party_B_Id=c4.C_Id
left join SYS_Company c5 on con1.Con_Party_A_Id=c5.C_Id
left join Sec_Info sec on sec.Sec_Id=mn.Con_Section_Id
left join Con_Contract jl on mn.Con_JL_Id = jl.Con_Id

    mn.Con_Approval_State != 3
    
        and mn.Te_Id = #{params.teId}
    
    
        
    
    
        and mn.Con_Evaluate_Id=#{params.conEvaluateId}
    
    
        and mn.Con_Scan_Up=#{params.conScanUp}
    
    
        and mn.con_Category=#{params.conCategory}
    
    
        and mn.con_Approval_State=#{params.conApprovalState}
    
    
        and(  mn.Con_Project_Id=#{params.conProjectId}
        or mn.con_Project_Id in (select child.P_Id from Pre_Project child where child.P_Parent_ID = #{params.conProjectId}))
    
    
        and mn.con_Type=#{params.conType}
    
    
        and mn.Con_Budget_Id=#{params.conBudgetId}
    
    
        and mn.Con_Is_History=#{params.conIsHistory}
    
    
        and mn.Con_State=#{params.conState}
    
    
        and mn.Con_Execution=#{params.conExecution}
    
    
        and mn.Con_Bidding_Type=#{params.conBiddingType}
    
    
        and mn.Con_Consortium=#{params.conConsortium}
    
    
        and mn.Con_Master_Con_Id=#{params.conMasterConId}
    
    
        and mn.Con_Multi_Subject=#{params.conMultiSubject}
    
    
        and mn.Con_Sup=#{params.conSup}
    
    
        and mn.Con_Currency=#{params.conCurrency}
    
    
        and mn.Con_Year=#{params.conYear}
    
    
        and mn.Con_Professional_Type=#{params.conProfessionalType}
    
    
        and mn.con_Section_Id=#{params.conSectionId}
    
    
        and mn.con_Is_Bidding=#{params.conIsBidding}
    
    
        and mn.Con_Involve_Funds=#{params.conInvolveFunds}
    
    
        and(  mn.Con_Project_Id=#{params.pId} or mn.con_Project_Id in (select child.P_Id from Pre_Project child where child.P_Parent_ID = #{params.pId}))
    
    
        and mn.Con_Purchase_Type=#{params.conPurchaseType}
    
    
        and mn.con_Category!='7'
    
    
        and pro.P_Advance_Fund=#{params.pAdvanceFund}
    
    
        and pro.P_Corporate_Risk=#{params.pCorporateRisk}
    
    
        and mn.Con_Is_Supply=#{params.conIsSupply}
    
    
        and mn.Con_Open_Bidding=#{params.conOpenBidding}
    
    
        and mn.Con_Pay_Category=#{params.conPayCategory}
    
    
        and mn.Con_Money_Total=#{params.conMoneyTotal}
    
    
        and mn.Con_Sup_Change_Money is not null and mn.Con_Sup_Change_Money != 0
    
    
        and (
        mn.Con_Party_B_Id=#{params.bUnitId}
        or mn.Con_Party_B1=#{params.bUnitId}
        or mn.Con_Party_B2=#{params.bUnitId}
        or mn.Con_Party_B3=#{params.bUnitId}
        or mn.Con_Party_B4=#{params.bUnitId}
        or mn.Con_Party_C_Id=#{params.bUnitId}
        or mn.Con_Party_D_Id=#{params.bUnitId}
        )
    
    
        and mn.Con_Serial_Number like concat('%',#{params.conSerialNumber},'%')
    
    
        and mn.Con_Original_Code like concat('%',#{params.conOriginalCode},'%')
    
    
        and mn.Con_Using_Type like concat('%',#{params.conUsingType},'%')
    
    
        and mn.Con_Create_User_Name like concat('%',#{params.conCreateUserName},'%')
    
    
        and mn.Con_Party_B_Legal like concat('%',#{params.conPartyBLegal},'%')
    
    
        and mn.Con_Party_B_Agent like concat('%',#{params.conPartyBAgent},'%')
    
    
        and mn.Con_Party_B_Poxy_Num like concat('%',#{params.conPartyBPoxyNum},'%')
    
    
        and mn.Con_Party_B_Agent_Tel like concat('%',#{params.conPartyBAgentTel},'%')
    
    
        and mn.Con_TD_Name like concat('%',#{params.conTdName},'%')
    
    
        and mn.Con_TD_Num like concat('%',#{params.conTdNum},'%')
    
    
        and mn.Con_TD_Mobile_Number like concat('%',#{params.conTdMobileNumber},'%')
    
    
        and mn.Con_Party_B_Pm like concat('%',#{params.conPartyBPm},'%')
    
    
        and mn.Con_Party_B_Pm_Cons_Nu like concat('%',#{params.conPartyBPmConsNu},'%')
    
    
        and mn.Con_Party_B_Pm_Idcard like concat('%',#{params.conPartyBPmIdcard},'%')
    
    
        
            
                and (INSTR(mn.con_Name,#{params.blSearch}) or INSTR(mn.con_Code,#{params.blSearch})
                or likePname(#{params.blSearch},pro.p_id)=true or INSTR(pro.P_Code,#{params.blSearch}))
            
            
                and (INSTR(mn.con_Name,#{params.blSearch}) or INSTR(mn.con_Code,#{params.blSearch})
                or INSTR(pro.P_Name,#{params.blSearch}) or INSTR(pro.P_Code,#{params.blSearch}))
            
        
    
    
        and mn.con_Name like concat('%',#{params.conName},'%')
    
    
        and mn.con_Code like concat('%',#{params.conCode},'%')
    
    
        
            
                and likePname(#{params.conProjectName},pro.p_id)=true
            
            
                and pro.P_Name like concat('%',#{params.conProjectName},'%')
            
        
    
    
        and CONCAT_WS('；', c.C_Name, cc1.C_Name, cc2.C_Name, cc3.C_Name, cc4.C_Name, cc5.C_Name, c3.C_Name, cc6.C_Name) like concat('%',#{params.conPartyBName},'%')
    
    
        
            
                and likeCname(#{params.conPartyAName},c1.c_id)=true
            
            
                and c1.C_Name like concat('%',#{params.conPartyAName},'%')
            
        
    
    
        
            
                and likeCname(#{params.conPartyAOtherName},c2.c_id)=true
            
            
                and c2.C_Name like concat('%',#{params.conPartyAOtherName},'%')
            
        
    
    
        and mn.Con_Id in (select Con_Id from Inv_Settlement_Apply where Sa_State=7)
    
    
        and mn.Con_Type in
        
            #{type}
        
    
    
        and mn.Con_Approval_State in
        
            #{state}
        
    
    
        and mn.ccm_Id is null
    


    
        order by mn.${params.sortFiled} ${params.sortType}
    
    
        order by ${params.sortSideFiled} ${params.sortType}
    
    
        order by mn.Con_Create_Time desc

select COALESCE(sum(mn.Con_Money_Total), 0)
from Con_Contract mn
where mn.Con_Approval_State = 7

    and mn.Te_Id = #{teId}

and (
    mn.Con_Party_B_Id in
    
        #{companyId}
    
    or mn.Con_Party_B1 in
    
        #{companyId}
    
    or mn.Con_Party_B2 in
    
        #{companyId}
    
    or mn.Con_Party_B3 in
    
        #{companyId}
    
    or mn.Con_Party_B4 in
    
        #{companyId}
    
    or mn.Con_Party_B5 in
    
        #{companyId}
    
    or mn.Con_Party_B6 in
    
        #{companyId}
    
    or mn.Con_Party_B7 in
    
        #{companyId}
    
    or mn.Con_Party_B8 in
    
        #{companyId}
    
    or mn.Con_Party_B9 in
    
        #{companyId}
    
    or mn.Con_Party_B10 in
    
        #{companyId}
    
)
